type agreementCutHeadingSource struct {
	Cut, PrivateCut                        agreementRemovedCommentDiagnosticReading
	Native, PrivateNative                  agreementNativeHeadingSource
	Plain, Page, PrivatePlain, PrivatePage agreementMixedNamespaceReading
	IDs, PrivateIDs                        []string
	Private                                string
	OriginalSpan, ProjectedSpan            graph.Span
	Ordinal                                int
	Valid                                  bool
}

// Comment removal can expose another heading while preserving every physical
// line boundary. Its whole name allocation, including repeated bases, must
// agree with the page before one source interval can own a missing check name.
func agreementCutHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementCutHeadingSource {
	r := agreementCutHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Cut = agreementCommentCutP0Reading(body)
	if !r.Cut.Valid {
		return r
	}
	r.Plain = agreementMixedNamespaceRead(r.Cut.Projected, agreementFootnoteGrammar)
	r.Page = agreementMixedNamespaceRead(r.Cut.Projected, agreementExclusiveCodeGrammar)
	if !r.Plain.Eligible || !r.Page.Eligible || !cmp.Equal(r.Plain, r.Page) {
		return r
	}
	r.IDs = agreementCutHeadingAllocate(r.Page.Bases)
	r.Native = agreementNativeHeadingReading(body)
	if !slices.Equal(r.IDs, page.Headings) || r.Native.Names[f.Fragment] || !slices.Equal(r.Native.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(r.Page.Headings) {
		return r
	}
	r.ProjectedSpan = r.Page.Headings[r.Ordinal]
	span := r.ProjectedSpan
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(r.Cut.Positions) {
		return r
	}
	words := r.Cut.Projected[span.Start:span.Stop]
	if words != "A" && words != "B" && words != "A-2" && words != "!" {
		return r
	}
	start := r.Cut.Positions[span.Start]
	for i, at := range r.Cut.Positions[span.Start:span.Stop] {
		if at != start+i || at < 0 || at >= len(body) || body[at] != words[i] {
			return r
		}
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + len(words)}
	private := []byte(body)
	copy(private[r.OriginalSpan.Start:r.OriginalSpan.Stop], strings.Repeat("q", len(words)))
	r.Private = string(private)
	r.PrivateCut = agreementCommentCutP0Reading(r.Private)
	r.PrivateNative = agreementNativeHeadingReading(r.Private)
	r.PrivatePlain = agreementMixedNamespaceRead(r.PrivateCut.Projected, agreementFootnoteGrammar)
	r.PrivatePage = agreementMixedNamespaceRead(r.PrivateCut.Projected, agreementExclusiveCodeGrammar)
	if !r.PrivateCut.Valid || !r.PrivatePlain.Eligible || !r.PrivatePage.Eligible || !cmp.Equal(r.PrivatePlain, r.PrivatePage) || !slices.Equal(r.Cut.Positions, r.PrivateCut.Positions) || !cmp.Equal(r.Cut.Check.Comments, r.PrivateCut.Check.Comments) || !slices.Equal(r.Native.Check.Targets, r.PrivateNative.Check.Targets) || !slices.Equal(r.PrivateNative.Check.Targets, judge.LinkTargets(r.Private)) {
		return r
	}
	expected := []byte(r.Cut.Projected)
	copy(expected[span.Start:span.Stop], strings.Repeat("q", len(words)))
	if string(expected) != r.PrivateCut.Projected || !cmp.Equal(r.Page.Headings, r.PrivatePage.Headings) || !cmp.Equal(r.Page.Code, r.PrivatePage.Code) || !cmp.Equal(r.Page.Fields, r.PrivatePage.Fields) || len(r.Page.Bases) != len(r.PrivatePage.Bases) || len(r.Page.Checks) != len(r.PrivatePage.Checks) {
		return r
	}
	for i := range r.Page.Bases {
		if i == r.Ordinal {
			if r.PrivatePage.Bases[i] != strings.Repeat("q", len(words)) || r.PrivatePage.Checks[i] != strings.Repeat("q", len(words)) {
				return r
			}
		} else if r.Page.Bases[i] != r.PrivatePage.Bases[i] || r.Page.Checks[i] != r.PrivatePage.Checks[i] {
			return r
		}
	}
	r.PrivateIDs = agreementCutHeadingAllocate(r.PrivatePage.Bases)
	r.Valid = true
	return r
}
func agreementCutHeadingAllocate(bases []string) []string {
	used := map[string]bool{}
	var ids []string
	for _, base := range bases {
		id := base
		for n := 2; used[id]; n++ {
			id = base + "-" + strconv.Itoa(n)
		}
		used[id] = true
		ids = append(ids, id)
	}
	return ids
}
func agreementCutHeadingEquation(ids []string, names map[string]bool, failures []agreementFailure) bool {
	expected := map[string]int{}
	for _, id := range ids {
		if !names[id] {
			f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Fragment: id, Direction: "page-only", Multiplicity: 1, PagePresent: true}
			expected[agreementSignature(&f)]++
		}
	}
	actual := map[string]int{}
	for i := range failures {
		f := &failures[i]
		if f.Property == "P4" {
			actual[agreementSignature(f)]++
		}
	}
	return maps.Equal(expected, actual)
}
func agreementCutHeadingProjection(source *agreementCutHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementCutHeadingEquation(source.IDs, source.Native.Names, before) || !agreementCutHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}
func agreementCutHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementCutHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementCutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementCutHeadingSelected(t *testing.T, r *agreementCutHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique cut heading declaration")
	}
	return selected
}
func TestAgreementCutHeadingOwnedSource(t *testing.T) {
	rows := agreementCutHeadingDeclarations()
	if len(rows) != 231 {
		t.Fatal("caught: complete cut heading declaration set")
	}
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			selected := agreementCutHeadingSelected(t, r)
			source := agreementCutHeadingReading(r.Body, &selected, &r.Page)
			if !source.Valid || !cmp.Equal(source, r.Source) || source.Private != r.Private {
				t.Fatalf("caught: complete cut heading physical source and whole namespace (-want +got):\n%s", cmp.Diff(r.Source, source))
			}
			span := source.OriginalSpan
			private := []byte(r.Body)
			if span.Start < 0 || span.Stop > len(private) || span.Stop <= span.Start {
				t.Fatal("caught: physical cut heading interval")
			}
			copy(private[span.Start:span.Stop], strings.Repeat("q", span.Stop-span.Start))
			if string(private) != r.Private || source.Ordinal < 0 || source.IDs[source.Ordinal] != selected.Fragment || !agreementCutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: complete cut heading signed source projection")
			}
		})
	}
}
func TestAgreementCutHeadingOwnedPublic(t *testing.T) {
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			raw, page, before := agreementProseP0Failures(t, r.Body)
			pr, pp, after := agreementProseP0Failures(t, r.Private)
			if raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !maps.Equal(agreementMixedCurrent(before), agreementMixedCurrent(r.Before)) || !maps.Equal(agreementMixedCurrent(after), agreementMixedCurrent(r.After)) || !agreementCutHeadingProjection(&r.Source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics) {
				t.Fatal("caught: complete cut heading public and diagnostic ledgers")
			}
			selected := agreementCutHeadingSelected(t, r)
			k, a, w := agreementCutHeadingDifference(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, before)
			if k != "debt" || a != "#1011 stage 8" || w != "judge" {
				t.Fatal("caught: exact cut heading authority and original source membership")
			}
		})
	}
}
func TestAgreementCutHeadingOwnedRefusals(t *testing.T) {
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementCutHeadingSelected(t, r)
			refuse := func(c agreementCase, x *agreementFailure, html string, page *agreementHTML, ds []render.Diagnostic, fs []agreementFailure) {
				t.Helper()
				k, a, w := agreementCutHeadingDifference(c, x, html, page, ds, fs)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: cut heading refuses changed complete source or context")
				}
			}
			for _, c := range []agreementCase{{Body: r.Body + "!"}, {Body: r.Body, Title: "outside"}, {Body: r.Body, Companions: capturedBodies{"outside.md": "outside"}}} {
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			c := agreementCase{Body: r.Body}
			refuse(c, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML, nil, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML+"!", &r.Page, r.Diagnostics, r.Before)
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "outside" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				refuse(c, &x, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			altered := r.Page
			altered.Headings = append(slices.Clone(r.Page.Headings), "outside")
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			altered = r.Page
			altered.Citations = append(slices.Clone(r.Page.Citations), agreementCitation{Target: "outside"})
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			ds := append(slices.Clone(r.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(c, &f, r.HTML, &r.Page, ds, r.Before)
			for j := range r.Before {
				fs := slices.Delete(slices.Clone(r.Before), j, j+1)
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, fs)
				if agreementCutHeadingProjection(&r.Source, fs, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every original cut heading receipt retained")
				}
			}
			for j := range r.After {
				fs := slices.Delete(slices.Clone(r.After), j, j+1)
				if agreementCutHeadingProjection(&r.Source, r.Before, fs, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every private cut heading receipt retained")
				}
			}
			source := r.Source
			source.IDs = append(slices.Clone(r.Source.IDs), "outside")
			if agreementCutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: whole cut heading source allocation retained")
			}
		})
	}
}
func TestAgreementCutHeadingOwnedCensus(t *testing.T) {
	rows := agreementCutHeadingProspects()
	if len(rows) != 621 {
		t.Fatal("caught: whole cut heading prospect roster")
	}
	qualified := map[[2]string]bool{}
	for i := range rows {
		r := &rows[i]
		raw, page, before := agreementProseP0Failures(t, r.Body)
		var selected agreementFailure
		seen := 0
		for j := range before {
			f := &before[j]
			if agreementSignature(f) == r.Selected {
				selected = *f
				seen++
			}
		}
		if seen != 1 {
			t.Fatal("caught: every original cut heading prospect exists")
		}
		source := agreementCutHeadingReading(r.Body, &selected, &page)
		eligible := false
		if source.Valid {
			pr, pp, after := agreementProseP0Failures(t, source.Private)
			eligible = agreementCutHeadingProjection(&source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics)
		}
		if eligible != r.Eligible {
			t.Fatalf("caught: whole cut heading eligibility and refusal set case=%s selected=%s got=%t want=%t", r.Case, r.Selected, eligible, r.Eligible)
		}
		if eligible {
			qualified[[2]string{r.Body, r.Selected}] = true
		}
	}
	declared := map[[2]string]bool{}
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		declared[[2]string{r.Body, r.Selected}] = true
	}
	if len(declared) != 231 || !maps.Equal(qualified, declared) {
		t.Fatal("caught: complete cut heading eligible declaration set")
	}
}
func TestAgreementCutHeadingOwnedProjectionRefusals(t *testing.T) {
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			reject := func(s *agreementCutHeadingSource, page, privatePage *agreementHTML, ds, pds []render.Diagnostic) {
				t.Helper()
				if agreementCutHeadingProjection(s, r.Before, r.After, page, privatePage, ds, pds) {
					t.Fatal("caught: cut heading refuses changed whole projection")
				}
			}
			reject(nil, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, nil, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, &r.Page, nil, r.Diagnostics, r.PrivateDiagnostics)
			s := r.Source
			s.Valid = false
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.IDs = append(slices.Clone(s.IDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.PrivateIDs = append(slices.Clone(s.PrivateIDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.Native.Names = maps.Clone(s.Native.Names)
			f := agreementCutHeadingSelected(t, r)
			s.Native.Names[f.Fragment] = true
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			pp := r.PrivatePage
			pp.Headings = append(slices.Clone(pp.Headings), "outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Citations = append(slices.Clone(pp.Citations), agreementCitation{Target: "outside"})
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Blocks = append(slices.Clone(pp.Blocks), "^outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			ds := append(slices.Clone(r.PrivateDiagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			reject(&r.Source, &r.Page, &r.PrivatePage, r.Diagnostics, ds)
		})
	}
}
func TestAgreementCutHeadingOwnedPhysicalRefusals(t *testing.T) {
	for i := range agreementCutHeadingDeclarations() {
		r := &agreementCutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementCutHeadingSelected(t, r)
			if agreementCutHeadingReading(r.Body, nil, &r.Page).Valid || agreementCutHeadingReading(r.Body, &f, nil).Valid {
				t.Fatal("caught: cut heading physical context")
			}
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				if agreementCutHeadingReading(r.Body, &x, &r.Page).Valid {
					t.Fatal("caught: cut heading refuses another physical property or signature")
				}
			}
			changed := r.Page
			changed.Headings = append(slices.Clone(changed.Headings), "outside")
			if agreementCutHeadingReading(r.Body, &f, &changed).Valid {
				t.Fatal("caught: cut heading refuses altered physical allocation")
			}
		})
	}
}
